class UserReader(Protocol):
    def get(self, user_id: UUID) -> User | None: ...

def find_user(reader: UserReader, user_id: UUID) -> User:
    user = reader.get(user_id)
    if user is None:
        raise UserNotFound(user_id)
    return user

